//! Panic reporting that mirrors the standard library's default format while
//! allowing an explicit location to be supplied.

use std::io::Write;
use std::sync::atomic::{AtomicBool, Ordering};

pub struct LocatedPanic {
    pub location: String,
    pub message: String,
}

static FIRST_PANIC: AtomicBool = AtomicBool::new(true);

fn os_tid() -> i64 {
    unsafe { libc::syscall(libc::SYS_gettid) as i64 }
}

pub fn install_hook() {
    std::panic::set_hook(Box::new(|info| {
        let (location, message) = if let Some(p) = info.payload().downcast_ref::<LocatedPanic>() {
            (p.location.clone(), p.message.clone())
        } else {
            let loc = info
                .location()
                .map(|l| format!("{}:{}:{}", l.file(), l.line(), l.column()))
                .unwrap_or_default();
            let msg = if let Some(s) = info.payload().downcast_ref::<&str>() {
                s.to_string()
            } else if let Some(s) = info.payload().downcast_ref::<String>() {
                s.clone()
            } else {
                "Box<dyn Any>".to_string()
            };
            (loc, msg)
        };
        let current = std::thread::current();
        let name = current.name().unwrap_or("<unnamed>").to_string();
        let mut out = format!(
            "\nthread '{}' ({}) panicked at {}:\n{}\n",
            name,
            os_tid(),
            location,
            message
        );
        if FIRST_PANIC.swap(false, Ordering::SeqCst) {
            let bt = std::env::var("RUST_BACKTRACE").unwrap_or_default();
            if bt.is_empty() || bt == "0" {
                out.push_str(
                    "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n",
                );
            }
        }
        let stderr = std::io::stderr();
        let mut lock = stderr.lock();
        let _ = lock.write_all(out.as_bytes());
        let _ = lock.flush();
    }));
}

/// Panic with a message attributed to the given source location.
pub fn panic_at(location: &str, message: String) -> ! {
    std::panic::panic_any(LocatedPanic {
        location: location.to_string(),
        message,
    })
}
