//! Minimal logger reproducing the output format used by the tool.

use std::io::Write;
use std::sync::atomic::{AtomicU8, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};

pub const ERROR: u8 = 1;
pub const WARN: u8 = 2;
pub const INFO: u8 = 3;
pub const DEBUG: u8 = 4;
pub const TRACE: u8 = 5;

static LEVEL: AtomicU8 = AtomicU8::new(INFO);

pub fn set_level(level: u8) {
    LEVEL.store(level, Ordering::SeqCst);
}

pub fn enabled(level: u8) -> bool {
    level <= LEVEL.load(Ordering::Relaxed)
}

fn thread_number() -> String {
    let id = format!("{:?}", std::thread::current().id());
    id.trim_start_matches("ThreadId(")
        .trim_end_matches(')')
        .to_string()
}

fn timestamp() -> String {
    let secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let day = secs % 86400;
    format!("{:02}:{:02}:{:02}", day / 3600, (day % 3600) / 60, day % 60)
}

fn emit(level: u8, target: &str, location: Option<&str>, msg: &str) {
    if !enabled(level) {
        return;
    }
    let name = match level {
        ERROR => "ERROR",
        WARN => "WARN",
        INFO => "INFO",
        DEBUG => "DEBUG",
        _ => "TRACE",
    };
    let mut line = String::new();
    if level >= DEBUG {
        line.push_str(&timestamp());
        line.push(' ');
    }
    line.push('[');
    line.push_str(name);
    line.push_str("] ");
    if level >= DEBUG {
        line.push('(');
        line.push_str(&thread_number());
        line.push_str(") ");
        line.push_str(target);
        line.push_str(": ");
    }
    if level >= TRACE {
        if let Some(loc) = location {
            line.push('[');
            line.push_str(loc);
            line.push_str("] ");
        }
    }
    line.push_str(msg);
    line.push('\n');
    if level == ERROR {
        let stderr = std::io::stderr();
        let mut l = stderr.lock();
        let _ = l.write_all(line.as_bytes());
        let _ = l.flush();
    } else {
        let stdout = std::io::stdout();
        let mut l = stdout.lock();
        let _ = l.write_all(line.as_bytes());
        let _ = l.flush();
    }
}

pub fn error(msg: &str) {
    emit(ERROR, "dirble", None, msg);
}

pub fn warn(msg: &str) {
    emit(WARN, "dirble", None, msg);
}

pub fn info(msg: &str) {
    emit(INFO, "dirble", None, msg);
}

pub fn debug(target: &str, msg: &str) {
    emit(DEBUG, target, None, msg);
}

pub fn trace(target: &str, location: &str, msg: &str) {
    emit(TRACE, target, Some(location), msg);
}
EOF
echo ok"}

