//! Loading of wordlists, prefix/extension lists and URI lists.

use crate::panics::panic_at;

/// Where a list file is loaded from; this only affects how failures are
/// reported.
#[derive(Clone, Copy, PartialEq)]
pub enum Origin {
    Lists,
    Hosts,
}

fn location(origin: Origin, line: u32, col: u32) -> String {
    match origin {
        Origin::Lists => format!("src/wordlist.rs:{}:{}", line, col),
        Origin::Hosts => format!("/workspace/src/wordlist.rs:{}:{}", line, col),
    }
}

const WINDOWS_1252_HIGH: [u32; 32] = [
    0x20AC, 0x0081, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021, 0x02C6, 0x2030, 0x0160, 0x2039,
    0x0152, 0x008D, 0x017D, 0x008F, 0x0090, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
    0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x009D, 0x017E, 0x0178,
];

fn decode_utf16(bytes: &[u8], little_endian: bool) -> String {
    let mut units = Vec::with_capacity(bytes.len() / 2);
    let mut i = 0;
    while i + 1 < bytes.len() {
        let u = if little_endian {
            u16::from_le_bytes([bytes[i], bytes[i + 1]])
        } else {
            u16::from_be_bytes([bytes[i], bytes[i + 1]])
        };
        units.push(u);
        i += 2;
    }
    char::decode_utf16(units.into_iter())
        .filter_map(|r| r.ok())
        .collect()
}

fn decode_single_byte(bytes: &[u8]) -> String {
    bytes
        .iter()
        .map(|&b| {
            if (0x80..0xA0).contains(&b) {
                char::from_u32(WINDOWS_1252_HIGH[(b - 0x80) as usize]).unwrap_or('\u{FFFD}')
            } else {
                b as char
            }
        })
        .collect()
}

/// Read a file and decode it to a string, guessing its encoding.
pub fn read_text(path: &str, origin: Origin) -> String {
    let bytes = match std::fs::read(path) {
        Ok(b) => b,
        Err(e) => panic_at(
            &location(origin, 112, 37),
            format!("called `Result::unwrap()` on an `Err` value: {:?}", e),
        ),
    };
    if bytes.is_empty() {
        panic_at(
            &location(origin, 130, 13),
            format!(
                "Error detecting file encoding of {} - is the file empty?",
                path
            ),
        );
    }
    if bytes.len() >= 2 && bytes[0] == 0xFF && bytes[1] == 0xFE {
        return decode_utf16(&bytes, true);
    }
    if bytes.len() >= 2 && bytes[0] == 0xFE && bytes[1] == 0xFF {
        return decode_utf16(&bytes, false);
    }
    match String::from_utf8(bytes) {
        Ok(s) => s,
        Err(e) => decode_single_byte(e.as_bytes()),
    }
}

/// Read a file into its individual lines.
pub fn lines_from_file(path: &str, origin: Origin) -> Vec<String> {
    read_text(path, origin)
        .lines()
        .map(|l| l.to_string())
        .collect()
}

/// Load a wordlist: one leading and one trailing slash is removed from each
/// entry.
pub fn load_wordlist(path: &str) -> Vec<String> {
    lines_from_file(path, Origin::Lists)
        .into_iter()
        .map(|line| {
            let mut s: &str = &line;
            if let Some(stripped) = s.strip_prefix('/') {
                s = stripped;
            }
            if let Some(stripped) = s.strip_suffix('/') {
                s = stripped;
            }
            s.to_string()
        })
        .collect()
}
