//! Conversion of parsed command line arguments into the global options.

use crate::cli;
use crate::panics::panic_at;
use crate::wordlist::{self, Origin};
use std::io::IsTerminal;

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
pub struct LengthRange {
    pub start: u64,
    pub end: u64,
}

impl LengthRange {
    pub fn contains(&self, len: u64) -> bool {
        self.start <= len && len <= self.end
    }
}

impl std::fmt::Display for LengthRange {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        if self.start == self.end {
            write!(f, "{}", self.start)
        } else {
            write!(f, "{}-{}", self.start, self.end)
        }
    }
}

#[derive(Clone, Copy, PartialEq)]
pub enum HttpVerb {
    Get,
    Head,
    Post,
}

pub struct GlobalOpts {
    pub hostnames: Vec<url::Url>,
    pub wordlist_files: Option<Vec<String>>,
    pub prefixes: Vec<String>,
    pub extensions: Vec<String>,
    pub extension_substitution: bool,
    pub max_threads: u32,
    pub wordlist_split: u32,
    pub max_recursion_depth: Option<i32>,
    pub scan_listable: bool,
    pub scrape_listable: bool,
    pub user_agent: Option<String>,
    pub username: Option<String>,
    pub password: Option<String>,
    pub cookies: Option<String>,
    pub headers: Vec<String>,
    pub proxy: Option<String>,
    pub ignore_cert: bool,
    pub timeout: u32,
    pub max_errors: u32,
    pub throttle: u32,
    pub show_htaccess: bool,
    pub disable_validator: bool,
    pub whitelist: Option<Vec<u32>>,
    pub blacklist: Vec<u32>,
    pub length_blacklist: Vec<LengthRange>,
    pub output_file: Option<String>,
    pub json_file: Option<String>,
    pub xml_file: Option<String>,
    pub verbose: u8,
    pub silent: bool,
    pub is_terminal: bool,
    pub colour: bool,
    pub http_verb: HttpVerb,
    pub scan_401: bool,
    pub scan_403: bool,
}

fn parse_length_ranges(values: Vec<String>) -> Vec<LengthRange> {
    let mut ranges = Vec::new();
    for value in values {
        if value.contains('-') {
            let parts: Vec<&str> = value.split('-').collect();
            if parts.len() != 2 {
                panic_at(
                    "src/arg_parse.rs:884:13",
                    "Ranges must be in the form `150-300`".to_string(),
                );
            }
            let start = match parts[0].parse::<u64>() {
                Ok(v) => v,
                Err(e) => panic_at(
                    "src/arg_parse.rs:890:18",
                    format!("Length must be integers: {:?}", e),
                ),
            };
            let end = match parts[1].parse::<u64>() {
                Ok(v) => v,
                Err(e) => panic_at(
                    "src/arg_parse.rs:894:22",
                    format!("Ranges must be in the form `150-300`: {:?}", e),
                ),
            };
            if start >= end {
                panic_at(
                    "src/arg_parse.rs:896:13",
                    "The start of a range must be smaller than the end".to_string(),
                );
            }
            ranges.push(LengthRange { start, end });
        } else {
            let len = match value.parse::<u64>() {
                Ok(v) => v,
                Err(e) => panic_at(
                    "src/arg_parse.rs:905:18",
                    format!("Length range must be integers: {:?}", e),
                ),
            };
            ranges.push(LengthRange { start: len, end: len });
        }
    }
    ranges.sort();
    ranges
}

fn env_flag(name: &str) -> Option<bool> {
    std::env::var(name).ok().map(|v| v != "0")
}

fn colour_enabled(is_terminal: bool, no_color: bool) -> bool {
    if !is_terminal || no_color {
        return false;
    }
    if env_flag("CLICOLOR_FORCE") == Some(true) {
        return true;
    }
    if env_flag("NO_COLOR").is_some() {
        return false;
    }
    env_flag("CLICOLOR").unwrap_or(true) && std::io::stdout().is_terminal()
}

pub fn get_args() -> GlobalOpts {
    let matches = cli::build_command().get_matches();

    // Gather the targets
    let mut hostnames: Vec<url::Url> = Vec::new();
    if let Some(h) = matches.get_one::<url::Url>("host") {
        hostnames.push(h.clone());
    }
    if let Some(hs) = matches.get_many::<url::Url>("extra_hosts") {
        for h in hs {
            hostnames.push(h.clone());
        }
    }
    if let Some(files) = matches.get_many::<String>("host_file") {
        for file in files {
            for line in wordlist::lines_from_file(file, Origin::Hosts) {
                match url::Url::parse(&line) {
                    Ok(u) if u.scheme() == "http" || u.scheme() == "https" => hostnames.push(u),
                    _ => println!("Invalid URL: {}", line),
                }
            }
        }
    }
    hostnames.sort_by(|a, b| a.as_str().cmp(b.as_str()));
    hostnames.dedup_by(|a, b| a.as_str() == b.as_str());
    if hostnames.is_empty() {
        println!("No valid hosts were provided - exiting");
        std::process::exit(2);
    }

    let length_blacklist = match matches.get_many::<String>("length_blacklist") {
        Some(v) => parse_length_ranges(v.cloned().collect()),
        None => Vec::new(),
    };

    // Prefixes
    let mut prefixes: Vec<String> = vec![String::new()];
    if let Some(p) = matches.get_many::<String>("prefixes") {
        prefixes.extend(p.cloned());
    }
    if let Some(files) = matches.get_many::<String>("prefix_file") {
        for file in files {
            prefixes.extend(wordlist::lines_from_file(file, Origin::Lists));
        }
    }
    prefixes.sort();
    prefixes.dedup();

    // Extensions
    let force_extension = matches.get_flag("force_extension");
    let mut extensions: Vec<String> = Vec::new();
    if !force_extension {
        extensions.push(String::new());
    }
    if let Some(x) = matches.get_many::<String>("extensions") {
        extensions.extend(x.cloned());
    }
    if let Some(files) = matches.get_many::<String>("extension_file") {
        for file in files {
            extensions.extend(wordlist::lines_from_file(file, Origin::Lists));
        }
    }
    extensions.sort();
    extensions.dedup();

    let wordlist_files = matches
        .get_many::<String>("wordlist")
        .map(|v| v.cloned().collect::<Vec<String>>());

    let disable_recursion = matches.get_flag("disable_recursion");
    let max_recursion_depth = if disable_recursion {
        Some(0)
    } else {
        matches.get_one::<i32>("max_recursion_depth").copied()
    };

    let cookies = matches
        .get_many::<String>("cookie")
        .map(|c| c.cloned().collect::<Vec<String>>().join("; "));
    let headers = matches
        .get_many::<String>("header")
        .map(|h| h.cloned().collect())
        .unwrap_or_default();

    let proxy = if matches.get_flag("burp") {
        Some("http://localhost:8080".to_string())
    } else if matches.get_flag("no_proxy") {
        Some(String::new())
    } else {
        matches.get_one::<String>("proxy").cloned()
    };

    let whitelist = matches
        .get_many::<u32>("code_whitelist")
        .map(|w| w.copied().collect::<Vec<u32>>());
    let blacklist = matches
        .get_many::<u32>("code_blacklist")
        .map(|b| b.copied().collect())
        .unwrap_or_default();
    let disable_validator = matches.get_flag("disable_validator") || whitelist.is_some();

    let output_all = matches.get_one::<String>("output_all").cloned();
    let output_file = matches
        .get_one::<String>("output_file")
        .cloned()
        .or_else(|| output_all.as_ref().map(|p| format!("{}.txt", p)));
    let json_file = matches
        .get_one::<String>("json_file")
        .cloned()
        .or_else(|| output_all.as_ref().map(|p| format!("{}.json", p)));
    let xml_file = matches
        .get_one::<String>("xml_file")
        .cloned()
        .or_else(|| output_all.as_ref().map(|p| format!("{}.xml", p)));

    let http_verb = match matches
        .get_one::<String>("http_verb")
        .map(|s| s.to_lowercase())
        .as_deref()
    {
        Some("head") => HttpVerb::Head,
        Some("post") => HttpVerb::Post,
        _ => HttpVerb::Get,
    };

    let is_terminal = std::io::stdout().is_terminal();
    let no_color = matches.get_flag("no_color");

    GlobalOpts {
        hostnames,
        wordlist_files,
        prefixes,
        extensions,
        extension_substitution: matches.get_flag("extension_substitution"),
        max_threads: *matches.get_one::<u32>("max_threads").unwrap_or(&10),
        wordlist_split: *matches.get_one::<u32>("wordlist_split").unwrap_or(&3),
        max_recursion_depth,
        scan_listable: matches.get_flag("scan_listable"),
        scrape_listable: matches.get_flag("scrape_listable"),
        user_agent: matches.get_one::<String>("user_agent").cloned(),
        username: matches.get_one::<String>("username").cloned(),
        password: matches.get_one::<String>("password").cloned(),
        cookies,
        headers,
        proxy,
        ignore_cert: matches.get_flag("ignore_cert"),
        timeout: *matches.get_one::<u32>("timeout").unwrap_or(&5),
        max_errors: *matches.get_one::<u32>("max_errors").unwrap_or(&5),
        throttle: matches.get_one::<u32>("throttle").copied().unwrap_or(0),
        show_htaccess: matches.get_flag("show_htaccess"),
        disable_validator,
        whitelist,
        blacklist,
        length_blacklist,
        output_file,
        json_file,
        xml_file,
        verbose: matches.get_count("verbose"),
        silent: matches.get_flag("silent"),
        is_terminal,
        colour: colour_enabled(is_terminal, no_color),
        http_verb,
        scan_401: matches.get_flag("scan_401"),
        scan_403: matches.get_flag("scan_403"),
    }
}
EOF
echo ok"}

