//! Making requests and interpreting their responses.

use crate::curl::{Easy, EasyConfig, Verb};
use crate::logger;
use crate::opts::{GlobalOpts, HttpVerb};
use crate::panics::panic_at;
use crate::scrape;

#[derive(Clone, Debug)]
pub struct RequestResponse {
    pub url: String,
    pub code: u32,
    pub content_len: usize,
    pub is_directory: bool,
    pub is_listable: bool,
    pub redirect_url: String,
    pub found_from_listable: bool,
    pub parent_index: usize,
}

pub fn easy_config(opts: &GlobalOpts) -> EasyConfig {
    EasyConfig {
        timeout: opts.timeout,
        user_agent: opts.user_agent.clone(),
        cookie: opts.cookies.clone(),
        headers: opts.headers.clone(),
        username: opts.username.clone(),
        password: opts.password.clone(),
        proxy: opts.proxy.clone(),
        ignore_cert: opts.ignore_cert,
        verb: match opts.http_verb {
            HttpVerb::Get => Verb::Get,
            HttpVerb::Head => Verb::Head,
            HttpVerb::Post => Verb::Post,
        },
    }
}

pub fn new_easy(opts: &GlobalOpts) -> Easy {
    Easy::new(&easy_config(opts))
}

/// Perform a single request, returning the response along with its body.
pub fn make_request(easy: &mut Easy, url: &str, parent_index: usize) -> (RequestResponse, Vec<u8>) {
    logger::trace(
        "dirble::request",
        "src/request.rs:114",
        &format!("Requesting {}", url),
    );
    let mut response = RequestResponse {
        url: url.to_string(),
        code: 0,
        content_len: 0,
        is_directory: false,
        is_listable: false,
        redirect_url: String::new(),
        found_from_listable: false,
        parent_index,
    };
    match easy.perform(url) {
        Err(e) => {
            println!("Curl error after requesting {} : {}", url, e);
            (response, Vec::new())
        }
        Ok(r) => {
            response.code = r.code;
            response.content_len = r.body.len();
            if r.code == 301 || r.code == 302 {
                match r.redirect_url() {
                    Some(u) => response.redirect_url = u.to_string(),
                    None => panic_at(
                        "src/request.rs:161:55",
                        "called `Option::unwrap()` on a `None` value".to_string(),
                    ),
                }
            }
            (response, r.body)
        }
    }
}

pub fn is_listable_content(content: &str) -> bool {
    content.contains("parent directory")
        || content.contains("up to higher level directory")
        || content.contains("directory listing for")
}

/// Request a directory (with trailing slash) and determine listability.
/// Returns the response and the lowercased content if it was listable.
fn request_directory(easy: &mut Easy, dir_url: &str, parent_index: usize) -> (RequestResponse, Option<String>) {
    let (mut response, body) = make_request(easy, dir_url, parent_index);
    response.is_directory = true;
    let mut listing = None;
    if response.code == 200 {
        let content = String::from_utf8_lossy(&body).to_lowercase();
        if is_listable_content(&content) {
            response.is_listable = true;
            listing = Some(content);
        }
    }
    (response, listing)
}

/// Fetch a URL generated from the wordlist and work out what it is.
/// The first entry of the returned list is the response to the URL itself,
/// any following entries were found by scraping.
pub fn fetch_url(easy: &mut Easy, url: &str, parent_index: usize, opts: &GlobalOpts) -> Vec<RequestResponse> {
    let (response, _body) = make_request(easy, url, parent_index);
