/// Return the URLs (as unparsed strings) of the links found in a listing
/// of the directory at `base`.
pub fn links(content: &str, base: &str) -> Vec<String> {
    let mut out = Vec::new();
    for href in hrefs(content) {
        let rel: String = if href.contains("://") {
            match href.strip_prefix(base) {
                Some(r) => r.to_string(),
                None => continue,
            }
        } else {
            if href.starts_with('/')
                || href.starts_with('?')
                || href.starts_with("./")
                || href.starts_with("../")
            {
                continue;
            }
            href
        };
        if rel.is_empty() {
            continue;
        }
        out.push(format!("{}{}", base, rel));
    }
    out
}
