                j += 1;
            }
            let attr_name: String = chars[an_start..j].iter().collect::<String>().to_lowercase();
            let mut k = j;
            while k < n && is_space(chars[k]) {
                k += 1;
            }
            let mut value = String::new();
            if k < n && chars[k] == '=' {
                k += 1;
                while k < n && is_space(chars[k]) {
                    k += 1;
                }
                if k < n && (chars[k] == '"' || chars[k] == '\'') {
                    let q = chars[k];
                    k += 1;
                    let vs = k;
                    while k < n && chars[k] != q {
                        k += 1;
                    }
