//! Detection of "not found" responses and the validator thread.

use crate::curl::Easy;
use crate::logger;
use crate::opts::GlobalOpts;
use crate::request::{make_request, new_easy, RequestResponse};
use std::collections::HashSet;
use std::sync::mpsc::{Receiver, Sender};
use std::sync::Arc;

#[derive(Clone, Debug)]
pub struct TargetValidator {
    pub code: u32,
    pub size: Option<usize>,
    pub diff: Option<usize>,
    pub dest: Option<String>,
}

impl std::fmt::Display for TargetValidator {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "(CODE:{}", self.code)?;
        if let Some(d) = &self.dest {
            write!(f, "|DEST:{}", d)?;
        }
        if let Some(s) = self.size {
            write!(f, "|SIZE:{}", s)?;
        }
        if let Some(d) = self.diff {
            write!(f, "|DIFF_SIZE:{}", d)?;
        }
        write!(f, ")")
    }
}

fn majority<T: PartialEq + Clone>(values: &[T]) -> Option<T> {
    if values[0] == values[1] || values[0] == values[2] {
        Some(values[0].clone())
    } else if values[1] == values[2] {
        Some(values[1].clone())
    } else {
        None
    }
}

fn url_diff(r: &RequestResponse) -> usize {
    let a = r.url.len() as i64;
    let b = r.content_len as i64;
    (a - b).unsigned_abs() as usize
}

impl TargetValidator {
    pub fn from_responses(responses: &[RequestResponse]) -> TargetValidator {
        let codes: Vec<u32> = responses.iter().map(|r| r.code).collect();
        let code = majority(&codes).unwrap_or(404);
        let mut v = TargetValidator {
            code,
            size: None,
            diff: None,
            dest: None,
        };
        if code == 404 {
            return v;
        }
        if code == 301 || code == 302 {
            let dests: Vec<String> = responses.iter().map(|r| r.redirect_url.clone()).collect();
            v.dest = majority(&dests);
            return v;
        }
        let sizes: Vec<usize> = responses.iter().map(|r| r.content_len).collect();
        v.size = majority(&sizes);
        if v.size.is_none() {
            let diffs: Vec<usize> = responses.iter().map(url_diff).collect();
            v.diff = majority(&diffs);
        }
        v
    }

    pub fn is_not_found(&self, r: &RequestResponse) -> bool {
        if r.code != self.code {
            return false;
        }
        if self.code == 404 {
            return true;
        }
        if self.code == 301 || self.code == 302 {
            return match &self.dest {
                Some(d) => *d == r.redirect_url,
                None => true,
            };
        }
        if let Some(s) = self.size {
            return s == r.content_len;
        }
        if let Some(d) = self.diff {
            return d == url_diff(r);
        }
        true
