const ALPHANUMERIC: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";

struct Rng(u64);

impl Rng {
    fn new() -> Rng {
        let t = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64)
            .unwrap_or(0x1234_5678);
        let addr = &t as *const u64 as u64;
        Rng(t ^ addr.rotate_left(17) ^ 0x9E37_79B9_7F4A_7C15 ^ (std::process::id() as u64) << 32)
    }

    fn next(&mut self) -> u64 {
        // splitmix64
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    fn string(&mut self, len: usize) -> String {
        (0..len)
            .map(|_| ALPHANUMERIC[(self.next() % ALPHANUMERIC.len() as u64) as usize] as char)
            .collect()
    }
}

fn slash_count(s: &str) -> i64 {
    s.matches('/').count() as i64
}

pub fn directory_depth(url: &str, target: &str) -> i64 {
    let mut u = url.to_string();
    if !u.ends_with('/') {
        u.push('/');
    }
    slash_count(&u) - slash_count(target)
}

fn validate(easy: &mut Easy, rng: &mut Rng, url: &str, parent_index: usize) -> Option<TargetValidator> {
    let base = match url::Url::parse(url) {
        Ok(u) => u,
        Err(_) => return None,
    };
    let mut responses = Vec::new();
    let mut errors = 0;
    for len in [10usize, 20, 30] {
        let random = rng.string(len);
        let target = match base.join(&random) {
            Ok(u) => u.as_str().to_string(),
            Err(_) => format!("{}{}", url, random),
        };
        let (response, _) = make_request(easy, &target, parent_index);
        if response.code == 0 {
            errors += 1;
        }
        responses.push(response);
    }
    if errors >= 2 {
        return None;
    }
    Some(TargetValidator::from_responses(&responses))
}

