    let mut rng = Rng::new();
    let mut seen: HashSet<String> = HashSet::new();
    let num_targets = opts.hostnames.len() as i64;
    while let Ok(req) = rx.recv() {
        if seen.contains(&req.url) {
            logger::debug(
                "dirble::validator_thread",
                &format!("{} has already been added to the scan queue", req.url),
            );
            let _ = tx.send(ValidatorResult::Jobs(Vec::new()));
            continue;
        }
        seen.insert(req.url.clone());

        if let Some(max) = opts.max_recursion_depth {
            let target = opts.hostnames[req.parent_index].as_str();
            if directory_depth(&req.url, target) > max as i64 {
                if !req.initial {
                    let _ = tx.send(ValidatorResult::Jobs(Vec::new()));
                }
                continue;
            }
        }

        let validator = if opts.disable_validator {
            None
        } else {
            match validate(&mut easy, &mut rng, &req.url, req.parent_index) {
                Some(v) => {
                    logger::info(&format!(
                        "Detected nonexistent paths for {} are {}",
                        req.url, v
                    ));
                    if v.code == 403 && !opts.scan_403 {
                        logger::info(&format!(
                            "Skipping {}: \n    Scanning of directories returning 403 is disabled.\n    Use the --scan-403 flag to scan this directory,\n    or provide valid session token or credentials.",
                            req.url
                        ));
                        let _ = tx.send(ValidatorResult::Jobs(Vec::new()));
                        continue;
                    }
                    if v.code == 401 && !opts.scan_401 {
                        logger::info(&format!(
                            "Skipping {}: \n    Scanning of directories returning 401 is disabled.\n    Use the --scan-401 flag to scan this directory,\n    or provide a valid session token or credentials.",
                            req.url
                        ));
                        let _ = tx.send(ValidatorResult::Jobs(Vec::new()));
                        continue;
                    }
                    Some(v)
                }
                None => {
                    logger::warn(&format!(
                        "{} errored too often during validation, skipping scanning",
                        req.url
                    ));
                    let _ = tx.send(ValidatorResult::Jobs(Vec::new()));
                    continue;
                }
            }
        };

        let mut split = opts.wordlist_split as i64;
        if req.initial {
            let increased = (opts.max_threads as i64 - 2) / num_targets;
            if increased > split {
                logger::info(&format!(
                    "Increasing wordlist-split for initial scan of {} to {}",
                    req.url, increased
                ));
                split = increased;
            }
        }

        let mut jobs = Vec::new();
        for prefix in &opts.prefixes {
            for extension in &opts.extensions {
                for start in 0..split {
                    jobs.push(ScanJob {
                        base: req.url.clone(),
                        parent_index: req.parent_index,
                        prefix: prefix.clone(),
                        extension: extension.clone(),
                        start: start as usize,
                        step: split as usize,
                        validator: validator.clone(),
                    });
                }
            }
        }
        let _ = tx.send(ValidatorResult::Jobs(jobs));
    }
}
