static SIGNAL_PIPE_WRITE: std::sync::atomic::AtomicI32 = std::sync::atomic::AtomicI32::new(-1);

extern "C" fn sigint_handler(_sig: libc::c_int) {
    let fd = SIGNAL_PIPE_WRITE.load(Ordering::SeqCst);
    if fd >= 0 {
        let b: u8 = 1;
        unsafe {
            libc::write(fd, &b as *const u8 as *const libc::c_void, 1);
        }
    }
}

fn install_interrupt_handler(tx: Sender<MainMsg>) {
    let mut fds = [0 as libc::c_int; 2];
    if unsafe { libc::pipe(fds.as_mut_ptr()) } != 0 {
        return;
    }
    let (read_fd, write_fd) = (fds[0], fds[1]);
    SIGNAL_PIPE_WRITE.store(write_fd, Ordering::SeqCst);
    thread::spawn(move || loop {
        let mut b: u8 = 0;
        let n = unsafe { libc::read(read_fd, &mut b as *mut u8 as *mut libc::c_void, 1) };
        if n == 1 {
            if tx.send(MainMsg::Interrupt).is_err() {
                return;
            }
        } else if n < 0 {
            let err = std::io::Error::last_os_error();
            if err.kind() != std::io::ErrorKind::Interrupted {
                return;
            }
        } else {
            return;
        }
    });
    unsafe {
        let mut action: libc::sigaction = std::mem::zeroed();
        action.sa_sigaction = sigint_handler as usize;
        action.sa_flags = libc::SA_RESTART;
        libc::sigemptyset(&mut action.sa_mask);
        libc::sigaction(libc::SIGINT, &action, std::ptr::null_mut());
    }
}

fn default_wordlist_paths() -> Vec<PathBuf> {
    let mut paths = Vec::new();
    let exe_dir = std::env::current_exe()
        .ok()
        .and_then(|p| p.parent().map(|d| d.to_path_buf()))
        .unwrap_or_else(|| PathBuf::from("."));
    paths.push(exe_dir.join("dirble_wordlist.txt"));
    paths.push(PathBuf::from("/usr/share/dirble/dirble_wordlist.txt"));
    paths.push(PathBuf::from("/usr/share/wordlists/dirble_wordlist.txt"));
    paths.push(PathBuf::from("/usr/share/wordlists/dirble/dirble_wordlist.txt"));
    paths
}

fn load_wordlists(opts: &GlobalOpts) -> (Vec<String>, String) {
    let mut words: Vec<String> = Vec::new();
    let banner_line;
    match &opts.wordlist_files {
        Some(files) => {
            for f in files {
                words.extend(wordlist::load_wordlist(f));
            }
            banner_line = format!("Wordlists: {}", files.join(" "));
        }
        None => {
            let paths = default_wordlist_paths();
            let mut msg = String::from("Checking for wordlist in:");
            for p in &paths {
                msg.push_str(&format!("\n - {}", p.display()));
            }
            logger::debug("dirble", &msg);
            let found = paths.iter().find(|p| p.exists());
            match found {
                Some(p) => {
                    let s = p.to_string_lossy().into_owned();
                    words.extend(wordlist::load_wordlist(&s));
                    banner_line = format!("Wordlist: {}", s);
                }
                None => {
                    logger::error("Unable to find default wordlist");
                    std::process::exit(1);
                }
            }
        }
    }
    words.sort();
    words.dedup();
    (words, banner_line)
}

fn list_banner(list: &[String], none: &str, some: &str) -> String {
    if list.len() == 1 && list[0].is_empty() {
        none.to_string()
    } else {
        let rest: Vec<&str> = list.iter().skip(1).map(|s| s.as_str()).collect();
        format!("{}: {}", some, rest.join(" "))
    }
}

fn print_banner(opts: &GlobalOpts, wordlist_line: &str) {
    let mut s = String::new();
    s.push_str(&format!("Dirble {}\n", cli::VERSION));
    s.push_str("Developed by Izzy Whistlecroft\n");
    let targets: Vec<&str> = opts.hostnames.iter().map(|h| h.as_str()).collect();
    s.push_str(&format!("Targets: {}\n", targets.join(" ")));
    s.push_str(wordlist_line);
    s.push('\n');
    s.push_str(&list_banner(&opts.prefixes, "No Prefixes", "Prefixes"));
    s.push('\n');
    s.push_str(&list_banner(&opts.extensions, "No Extensions", "Extensions"));
    s.push('\n');
    if opts.length_blacklist.is_empty() {
        s.push_str("No lengths hidden\n");
    } else {
        let ranges: Vec<String> = opts.length_blacklist.iter().map(|r| r.to_string()).collect();
        s.push_str(&format!("Hidden lengths: [{}]\n", ranges.join(", ")));
    }
    println!("{}", s);
}
