            banner_line = format!("Wordlists: {}", files.join(" "));
        }
        None => {
            let paths = default_wordlist_paths();
            let mut msg = String::from("Checking for wordlist in:");
            for p in &paths {
                msg.push_str(&format!("\n - {}", p.display()));
            }
            logger::debug("dirble", &msg);
            let found = paths.iter().find(|p| p.exists());
            match found {
                Some(p) => {
                    let s = p.to_string_lossy().into_owned();
                    words.extend(wordlist::load_wordlist(&s));
                    banner_line = format!("Wordlist: {}", s);
                }
                None => {
                    logger::error("Unable to find default wordlist");
                    std::process::exit(1);
                }
            }
        }
    }
    words.sort();
    words.dedup();
    (words, banner_line)
}

fn list_banner(list: &[String], none: &str, some: &str) -> String {
    if list.len() == 1 && list[0].is_empty() {
        none.to_string()
    } else {
        let rest: Vec<&str> = list.iter().skip(1).map(|s| s.as_str()).collect();
        format!("{}: {}", some, rest.join(" "))
    }
}

fn print_banner(opts: &GlobalOpts, wordlist_line: &str) {
    let mut s = String::new();
    s.push_str(&format!("Dirble {}\n", cli::VERSION));
    s.push_str("Developed by Izzy Whistlecroft\n");
    let targets: Vec<&str> = opts.hostnames.iter().map(|h| h.as_str()).collect();
    s.push_str(&format!("Targets: {}\n", targets.join(" ")));
    s.push_str(wordlist_line);
    s.push('\n');
    s.push_str(&list_banner(&opts.prefixes, "No Prefixes", "Prefixes"));
    s.push('\n');
    s.push_str(&list_banner(&opts.extensions, "No Extensions", "Extensions"));
    s.push('\n');
    if opts.length_blacklist.is_empty() {
        s.push_str("No lengths hidden\n");
    } else {
        let ranges: Vec<String> = opts.length_blacklist.iter().map(|r| r.to_string()).collect();
        s.push_str(&format!("Hidden lengths: [{}]\n", ranges.join(", ")));
    }
    println!("{}", s);
}
