    let base = url::Url::parse(&job.base).ok();
    let mut easy = request::new_easy(opts);
    let mut consecutive_errors: u32 = 0;
    let words = &shared.wordlist;
    let mut index = job.start;
    while job.step > 0 && index < words.len() {
        let word = &words[index];
        index += job.step;
        let path = if opts.extension_substitution {
            if word.contains("%EXT%") {
                format!("{}{}", job.prefix, word.replace("%EXT%", &job.extension))
            } else {
